#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# scripts/ci/wizard.sh — CI's two self-hosted runners (#2253), as Mitchell
# ruled on 2026-10-07 (#2218): a Hetzner dedicated Linux server, labelled
# `dax-build`, for the build, clippy, the tests, the framework lane and the
# bench series; and a rented Apple-silicon Mac mini, labelled `dax-oracle`,
# for the oracle job against the pinned keg. This walks the steps only a
# person can take (ordering each machine, the SSH key, the registration
# token, auto-login, the stash, billing) and runs
# scripts/ci/runner.sh on each machine over SSH for the rest. Its last stage
# deletes DAX_BUILD_RUNNER, the variable that held the Linux jobs on a
# GitHub-hosted image until the server was online (#2477,
# scripts/ci/README.md), and starts the first run on both runners.
#
#   scripts/ci/wizard.sh            from the repository's checkout
#   DRY_RUN=1 scripts/ci/wizard.sh  every stage, with each command that
#                                   would change a machine, GitHub or a
#                                   secret printed instead of run
#
# Values are kept in $DAX_RUNNERS_ENV (default
# ~/.config/dax-php/runners.env), never in the repository, and offered as
# the default when it is run again. Every stage can be run again: runner.sh
# keeps what already stands.

ENV_FILE="${DAX_RUNNERS_ENV:-$HOME/.config/dax-php/runners.env}"
mkdir -p "$(dirname "$ENV_FILE")"
cd "$(git rev-parse --show-toplevel)"
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
REPO_URL="https://github.com/$REPO"

# act CMD... — run a command that changes a machine, GitHub or a secret;
# under DRY_RUN=1, print it instead.
act() {
  if [[ "${DRY_RUN:-}" == 1 ]]; then note "dry run, not run: $*"; else "$@"; fi
}
# ssh_to HOST CMD... — SSH with the key this wizard set up.
ssh_to() { ssh -i "$SSH_KEY" -o StrictHostKeyChecking=accept-new "$@"; }
# token — a runner registration token for this repository, fresh: one lasts
# an hour, so it is fetched right before the machine that uses it.
token() {
  if [[ "${DRY_RUN:-}" == 1 ]]; then printf 'DRY-RUN-TOKEN'; return; fi
  gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token
}

TOTAL_STAGES=11

banner "dax-php CI: the Hetzner server and the Mac mini as runners"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "The SSH key both machines are ordered with"
say "One ed25519 key, used by this wizard to reach both machines."
ask SSH_KEY "Path of the private key (Enter for ~/.ssh/dax-ci):"
SSH_KEY="${SSH_KEY:-$HOME/.ssh/dax-ci}"
SSH_KEY="${SSH_KEY/#\~/$HOME}"
if [[ ! -f "$SSH_KEY" ]]; then
  if confirm "No key at $SSH_KEY. Create one?"; then
    act ssh-keygen -t ed25519 -N "" -C "dax-php CI runners" -f "$SSH_KEY"
  fi
fi
write_env SSH_KEY "$SSH_KEY"
step "The public key, which both providers ask for:"
note "$(cat "$SSH_KEY.pub" 2>/dev/null || echo "(not created: dry run)")"
if [[ "${DRY_RUN:-}" != 1 && -f "$SSH_KEY.pub" ]] && command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$SSH_KEY.pub" && note "(copied to the clipboard)"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: order the dedicated Linux server"
say "A quiet AX-class server, which #1902's A/A-bounded bench readings need."
open_url "https://robot.hetzner.com/key/index"
step "Robot → Key management → New key: paste the public key from stage 1."
open_url "https://www.hetzner.com/dedicated-rootserver/matrix-ax/"
step "Pick an AX model (AMD, NVMe; 64 GB RAM or more builds the workspace well) and a location."
step "Operating system: Ubuntu 26.04 — runner.sh refuses any other (packages.txt, #1724)."
step "  If the order form does not offer 26.04, order with the Rescue system and run"
step "  'installimage' in it, choosing Ubuntu 26.04; the key from stage 1 is offered there too."
step "Add the key from stage 1 to the order, and order. Hetzner mails when it is ready."
step "Robot → Servers → the server: copy its main IPv4 address."
ask LINUX_HOST "The server's IPv4 address:"
write_env LINUX_HOST "$LINUX_HOST"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Scaleway: rent the Apple-silicon Mac mini"
say "The oracle job runs here, against the pinned macOS keg (oracle.toml)."
open_url "https://console.scaleway.com/project/credentials"
step "Project → Credentials → SSH keys → Add SSH key: paste the public key from stage 1."
open_url "https://console.scaleway.com/apple-silicon/servers"
step "Create a Mac mini: Apple silicon (M2 or newer), the newest macOS offered."
step "When it is ready, its page shows the IP address and the SSH user name."
ask MAC_HOST "The Mac mini's IP address:"
ask MAC_USER "The SSH user name on its page:"
write_env MAC_HOST "$MAC_HOST"
write_env MAC_USER "$MAC_USER"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Both machines answer over SSH"
for target in "root@$LINUX_HOST" "$MAC_USER@$MAC_HOST"; do
  until act ssh_to -o BatchMode=yes -o ConnectTimeout=10 "$target" true; do
    warn "$target does not answer with the key yet (a new server can take minutes)."
    confirm "Try again?" || { printf '  %s✗ %s does not answer; run the wizard again once it does%s\n' "$RED" "$target" "$RESET"; exit 1; }
  done
  printf '  %s✓%s %s answers\n' "$GREEN" "$RESET" "$target"
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The Linux server becomes the runner labelled dax-build"
say "runner.sh linux, as root: packages, Docker, a 'runner' user, rustup, and the"
say "runner as a systemd service. A registration token is fetched for it now; your"
say "gh login needs admin on $REPO."
if confirm "Lay the server down as $REPO's runner 'dax-build'?"; then
  LINUX_TOKEN=$(token)
  act ssh_to "root@$LINUX_HOST" mkdir -p /root/dax-ci
  act scp -i "$SSH_KEY" scripts/ci/runner.sh scripts/ci/pinned-php.sh scripts/ci/stash.sh "root@$LINUX_HOST:/root/dax-ci/"
  act ssh_to "root@$LINUX_HOST" /root/dax-ci/runner.sh linux --url "$REPO_URL" --token "$LINUX_TOKEN"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The Mac mini logs in on boot"
say "The runner is a launchd agent of $MAC_USER, which runs only while that user is"
say "logged in, so the Mac must log in by itself after a restart."
open_url "vnc://$MAC_USER@$MAC_HOST"
step "In Screen Sharing (the password is on the server's Scaleway page):"
step "System Settings → Users & Groups → 'Automatically log in as' → $MAC_USER."
step "If FileVault is on, macOS offers no automatic login: turn FileVault off first"
step "  (System Settings → Privacy & Security → FileVault)."
pause "Press Enter once automatic login is set"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The Mac mini becomes the runner labelled dax-oracle"
say "runner.sh mac, as $MAC_USER: Homebrew (sudo asks for $MAC_USER's password once),"
say "rustup, the pinned php by md5, and the runner. The pin is rendered here, by"
say "xtask, from oracle.toml."
if confirm "Lay the Mac down as $REPO's runner 'dax-oracle'?"; then
  pin=$(mktemp)
  cargo xtask status --section oracle --format json > "$pin"
  note "the pin: php $(jq -r .binary.version "$pin") at $(jq -r .binary.path "$pin"), md5 $(jq -r .binary.md5 "$pin")"
  MAC_TOKEN=$(token)
  act ssh_to "$MAC_USER@$MAC_HOST" mkdir -p dax-ci
  act scp -i "$SSH_KEY" scripts/ci/runner.sh scripts/ci/pinned-php.sh "$MAC_USER@$MAC_HOST:dax-ci/"
  act scp -i "$SSH_KEY" "$pin" "$MAC_USER@$MAC_HOST:dax-ci/oracle.json"
  act ssh_to -t "$MAC_USER@$MAC_HOST" dax-ci/runner.sh mac --url "$REPO_URL" --token "$MAC_TOKEN" --pin dax-ci/oracle.json
  rm -f "$pin"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Both runners are online with their labels"
open_url "$REPO_URL/settings/actions/runners"
if [[ "${DRY_RUN:-}" == 1 ]]; then
  note "dry run, not read: gh api repos/$REPO/actions/runners"
else
  gh api "repos/$REPO/actions/runners" \
    --jq '.runners[] | "  \(.name): \(.status), labels \([.labels[].name] | join(", "))"'
fi
step "Expect two, online: one labelled dax-build and Linux, one dax-oracle and macOS."
step "A runner missing here: run its stage again; runner.sh keeps what already stands."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The stash every job hands off through"
say "The jobs keep what they hand each other on the server (scripts/ci/stash.sh),"
say "not as GitHub artifacts, which count against the account's storage (#3554)."
say "One key, a repository secret, reaches it from every runner; the server holds it"
say "to rrsync over ~runner/dax-stash, and your key from stage 1 reads it, for"
say "xtask phpt --against. The settings are the repository's: DAX_STASH and"
say "DAX_STASH_HOST_KEY, variables, and DAX_STASH_KEY, a secret. Stage 5 laid the"
say "directory and its prune timer down; run it again first on a server laid before."
STASH_KEY="$(dirname "$SSH_KEY")/dax-stash-ci"
if confirm "Authorize the stash's keys on the server and set the repository's stash settings?"; then
  [[ -f "$STASH_KEY" ]] || act ssh-keygen -t ed25519 -N "" -C "dax-php CI stash" -f "$STASH_KEY"
  # Each key held to rrsync over the stash alone: the jobs' to read and
  # write, the person's to read.
  keys=(
    "restrict,command=\"rrsync /home/runner/dax-stash\" $(cat "$STASH_KEY.pub" 2>/dev/null || echo "(not created: dry run)")"
    "restrict,command=\"rrsync -ro /home/runner/dax-stash\" $(cat "$SSH_KEY.pub" 2>/dev/null || echo "(not created: dry run)")"
  )
  # shellcheck disable=SC2016 # the script is the server's, its $f its own
  printf '%s\n' "${keys[@]}" | act ssh_to "root@$LINUX_HOST" 'f=/home/runner/.ssh/authorized_keys
    install -d -m 700 -o runner -g runner /home/runner/.ssh && touch "$f"
    while IFS= read -r key; do grep -qxF "$key" "$f" || echo "$key" >> "$f"; done
    chown runner:runner "$f" && chmod 600 "$f"'
  # The host key as the server states it over the connection stage 4
  # checked, so no job takes the first key it is offered.
  if [[ "${DRY_RUN:-}" == 1 ]]; then
    host_key="$LINUX_HOST ssh-ed25519 DRY-RUN"
  else
    host_key="$LINUX_HOST $(ssh_to "root@$LINUX_HOST" cut -d' ' -f1,2 /etc/ssh/ssh_host_ed25519_key.pub)"
  fi
  if [[ "${DRY_RUN:-}" == 1 ]]; then
    note "dry run, not set: the variables DAX_STASH=runner@$LINUX_HOST and DAX_STASH_HOST_KEY, the secret DAX_STASH_KEY"
  else
    set_var DAX_STASH "runner@$LINUX_HOST"
    set_var DAX_STASH_HOST_KEY "$host_key"
    set_secret DAX_STASH_KEY "$(cat "$STASH_KEY")"
  fi
  if act rsync -e "ssh -i $SSH_KEY -o BatchMode=yes" --list-only "runner@$LINUX_HOST:" >/dev/null; then
    printf '  %s✓%s your key reads the stash at runner@%s\n' "$GREEN" "$RESET" "$LINUX_HOST"
  else
    warn "your key does not read the stash at runner@$LINUX_HOST; run this stage again"
  fi
  step "To fetch CI's phpt runs (xtask phpt --against) from this machine:"
  note "export DAX_STASH=runner@$LINUX_HOST RSYNC_RSH='ssh -i $SSH_KEY'"
else
  warn "No stash: every hand-off between jobs stays a GitHub artifact, against the account's storage."
  SKIPPED+=("the stash: run this stage again")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Billing"
say "Self-hosted jobs spend no Actions minutes, but GitHub started no job at all while"
say "the account's billing failed (#2218)."
open_url "https://github.com/settings/billing"
step "Clear the failed payment, or the budget that stops Actions, so jobs start again."
step "Hosted macOS minutes are no longer used; a budget of 0 for them is safe."
step "Hosted Linux minutes stop once the next stage deletes DAX_BUILD_RUNNER."
pause "Press Enter once billing is settled"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "The Linux jobs come home: DAX_BUILD_RUNNER deleted, then the first run"
say "While DAX_BUILD_RUNNER is set, the Linux jobs run on a GitHub-hosted image and"
say "both oracle jobs are skipped (scripts/ci/README.md). With both runners online"
say "(stage 8), deleting it puts every job on dax-build and dax-oracle again; nothing"
say "in the workflows changes."
if [[ "${DRY_RUN:-}" == 1 ]]; then
  note "dry run, not read: gh variable list --repo $REPO"
  held=yes
else
  held=$(gh variable list --repo "$REPO" --json name --jq '.[] | select(.name == "DAX_BUILD_RUNNER") | "yes"')
fi
if [[ "$held" != yes ]]; then
  printf '  %s✓%s DAX_BUILD_RUNNER is not set; every job is on the self-hosted pair\n' "$GREEN" "$RESET"
elif confirm "Delete DAX_BUILD_RUNNER, so the jobs wait for dax-build and dax-oracle?"; then
  act gh variable delete DAX_BUILD_RUNNER --repo "$REPO"
else
  warn "DAX_BUILD_RUNNER is still set: the Linux jobs stay hosted and the oracle jobs skipped."
  SKIPPED+=("delete the variable: gh variable delete DAX_BUILD_RUNNER --repo $REPO")
fi
if confirm "Run the nightly workflow on main now (its Mac oracle job)?"; then
  act gh workflow run nightly.yml --repo "$REPO" --ref main
  open_url "$REPO_URL/actions/workflows/nightly.yml"
  step "Its 'oracle' job should start on dax-oracle; the next push to main runs harness.yml on dax-build."
  step "Post the run's link on the ticket this wizard came with, so its boxes can be ticked."
fi

finish
